}$ (car $\\ln(1)=0$)."]}},{"blanks":[{"expectedAnswer":"{{if:m==1|\\ln(2)|\\ln({{eval:m+1}})-\\ln({{m}})}}"}],"statement":"Calcule la valeur exacte de $\\displaystyle\\int_{0}^{1}\\dfrac{2x}{x^2+{{m}}}\\,\\mathrm{d}x$.\n\n$?$","variables":[{"name":"m","expression":"1..6"}],"correction":{"steps":["Avec $u(x)=x^2+{{m}}>0$ et $u'(x)=2x$, l'intégrande est $\\dfrac{u'}{u}$ : une primitive est $\\ln(x^2+{{m}})$.","$\\displaystyle\\int_{0}^{1}\\dfrac{2x}{x^2+{{m}}}\\,\\mathrm{d}x=\\left[\\ln(x^2+{{m}})\\right]_0^1={{if:m==1|\\ln(2)-\\ln(1)=|}}\\textcolor{{{color:primary.0}}}{{{if:m==1|\\ln(2)|\\ln({{eval:m+1}})-\\ln({{m}})}}}${{if:m==1|.|, soit $\\ln\\left(\\dfrac{ {{eval:m+1}} }{ {{m}} }\\right)$.}}"]}},{"blanks":[{"expectedAnswer":"{{eval:2*m+1}}"}],"statement":"Calcule la valeur exacte de $\\displaystyle\\int_{0}^{1}4x(x^2+{{m}})\\,\\mathrm{d}x$.\n\n$?$","variables":[{"name":"m","expression":"1..9"}],"correction":{"steps":["Avec $u(x)=x^2+{{m}}$, $u'(x)=2x$ : $4x(x^2+{{m}})=2u'(x)u(x)$, dont une primitive est $u^2$, soit $(x^2+{{m}})^2$.","$\\displaystyle\\int_{0}^{1}4x(x^2+{{m}})\\,\\mathrm{d}x=\\left[(x^2+{{m}})^2\\right]_0^1={{eval:(1+m)^2}}-{{eval:m^2}}=\\textcolor{{{color:primary.0}}}{{{eval:2*m+1}}}$."]}},{"statement":"Calcule la valeur exacte de $\\displaystyle\\int_{ {{m}} }^{ {{n}} }\\left({{eval:3*a*x^2+2*b*x+c}}\\right)\\mathrm{d}x$.\n\n$?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1..4;±"},{"name":"b","expression":"1..4;±"},{"name":"c","expression":"1..4;±"},{"name":"m","expression":"-2|-1"},{"name":"n","expression":"1|2"}],"conditions":["a*(n^3-m^3)+b*(n^2-m^2)+c*(n-m) != 0"],"blanks":[{"expectedAnswer":"{{eval:a*(n^3-m^3)+b*(n^2-m^2)+c*(n-m)}}","expectedErrors":[{"answer":"{{eval:-(a*(n^3-m^3)+b*(n^2-m^2)+c*(n-m))}}","message":"On calcule $F({{n}})-F({{m}})$ : la borne du haut moins la borne du bas.","label":"F(a) − F(b)"},{"answer":"{{eval:a*n^3+b*n^2+c*n}}","message":"Tu as oublié de retrancher $F({{m}})$, qui ne vaut pas $0